  kid_friendly, technical, surface, fee, permit) VALUES ('mount-timpanogos-timpooneke', 'utah-county', 'Mount Timpanogos via Timpooneke', 'American Fork Canyon / Alpine Loop', 'The classic route to the summit of Timp, the second-highest peak in the Wasatch. Climbs past Scout Falls and through alpine basins full of wildflowers and mountain goats before a rocky final ridge to the summit hut.', 'Start before sunrise to beat afternoon thunderstorms. The final ridge is exposed and the saddle often holds snow into July.', 40.4316, -111.6386, 14.6, 4400, 11752, 'out-and-back', 10, 'Strenuous', 424, '["summit","views","wildflowers","waterfall","wildlife"]', '["hike","trail-run"]', '["summer","fall"]', 'leash', 0, 1, 'dirt / talus', 'American Fork Canyon recreation fee', NULL)
